Lemma new_chunk_apart_pre : forall Σ' (m : mem) pre p n live0 frs usp a,
  ART RT Σ' m -> rt_live RT Σ' = pre ++ (p, n) :: live0 -> rt_frames RT Σ' = frs ->
  rt_sp0 RT Σ' - STACK_WIN <= usp ->
  aclient live0 frs usp a -> a < p \/ p + n <= a.
